// 有限页只消耗真正本人来源；本夹具不冒正式World或GUI。
#include "visit_appointment_test_fixture.hpp"
#include "resident/domains/interaction/visit_appointments/visit_appointment_boundary.hpp"
namespace {
Outcome<BoundaryValue> page(InvitationFixture& f,Integer cursor=0,Integer offers=0){VisitAppointmentMeetingState meetings;return query_visit_appointments(f.common,f.messages,f.catalog,f.appointments,f.prior,f.interactions,f.dialogues,f.access,f.catalog2,f.state,meetings,cursor,offers);}
const BoundaryValue::Array& list(const BoundaryValue& page,const char* name){auto* values=page.find(name);need(values&&values->as<BoundaryValue::Array>(),"page contains finite array");return *values->as<BoundaryValue::Array>();}
}
int main(){try{
 InvitationFixture f;auto message=f.original();f.meet("recipient","offer_invitation");auto before=page(f);need(before.ok&&before.value.find("ok")&&before.value.find("source_identity")&&boundary::get_string(before.value,"observer_actor_id","page")=="recipient","actual page uses original source identity and controlled observer");need(list(before.value,"offers").size()==1,"actual received note and current provider say create explicit offer button");auto offer=f.commit("recipient",OfferVisitAppointment{"invitation",message});need(offer.ok,"actual invitation written");f.interactions.interactions.clear();f.common.state().metadata.player_actor_id="sender";auto far=page(f);need(far.ok&&list(far.value,"rows").empty(),"uncollected distant invitation and dates stay unknown");
 f.meet("sender","collect_invitation");auto pending=page(f);need(pending.ok&&list(pending.value,"rows").size()==1,"real custodian can show one pending physical reply");const auto& hidden=list(pending.value,"rows")[0];need(!hidden.find("place_id")&&!hidden.find("earliest_tick")&&!hidden.find("terms_text")&&!hidden.find("other_actor_id"),"pending physical reply exposes no uncollected terms or remote person");need(boundary::get_string(list(hidden,"actions")[0],"command","action")=="collect_visit_appointment","only physical collection is offered before actual knowledge");
 auto quote=f.prepare("sender",CollectVisitAppointment{offer.value});need(quote.ok,"actual collection preview");auto encoded_quote=encode_visit_appointment_quote(quote.value);need(!encoded_quote.find("place_id")&&!encoded_quote.find("earliest_tick")&&!encoded_quote.find("accept_before_tick"),"preview quote cannot leak uncollected invitation terms");auto collected=f.commit("sender",CollectVisitAppointment{offer.value});need(collected.ok,"actual physical collection");auto learned=page(f);need(learned.ok&&list(learned.value,"rows")[0].find("terms_text"),"only actual collection reveals frozen times and place");auto accepted=f.commit("sender",AcceptVisitAppointment{offer.value,collected.value});need(accepted.ok,"explicit acceptance remains separate");f.common.state().metadata.player_actor_id="recipient";f.interactions.interactions.clear();auto own=page(f);const auto& original=list(own.value,"rows")[0];need(!original.find("acceptance_fact_id")&&!original.find("collection_fact_id"),"inviter page cannot expose distant other acceptance or collection");
 // 17份均沿原Leave/Receive生成；现场报价不是接受且未发邀，不相互制造承诺冲突。
 InvitationFixture many;for(int i=0;i<17;++i)many.original();many.meet("recipient","offer_invitation");auto first=page(many);need(first.ok&&list(first.value,"offers").size()==16&&first.value.find("next_offer_cursor")&&!first.value.find("next_cursor"),"offer list has its own exact finite first page");auto last=page(many,0,16);need(last.ok&&list(last.value,"offers").size()==1&&!last.value.find("next_offer_cursor"),"offer page terminates without synthetic negative cursor");need(!page(many,-1).ok&&!page(many,0,18).ok,"invalid cursors fail instead of scanning an unbounded UI list");
 std::cout<<checks<<" finite invitation view source checks; runtime and GUI deferred\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
